const els = {photoInput:$('#photoInput'),photoPreview:$('#photoPreview'),photoDrop:$('#photoDrop'),status:$('#analysisStatus'),results:$('#resultsSection'),suggestions:$('#suggestions'),broad:$('#broadRecognition'),quickFoods:$('#quickFoods'),recipeControls:$('#recipeControls'),servings:$('#servingsInput'),search:$('#foodSearch'),searchResults:$('#searchResults'),foodItems:$('#foodItems'),cal:$('#mealCalories'),protein:$('#mealProtein'),carbs:$('#mealCarbs'),fat:$('#mealFat'),history:$('#mealHistory')};
const todayKey = new Date().toLocaleDateString('en-CA');
let classifier; let activePhoto=''; let previewUrl=''; let candidates=[]; let selectedFood=null; let mealFoods=[]; let recipeType=''; let servingCount=4;
let allMeals=JSON.parse(localStorage.getItem('comida-clara-meals')||'[]');
let meals=allMeals.filter(m=>m.day===todayKey);
