try{const saved=JSON.parse(localStorage.getItem('comida-clara-protein-settings')||'{}');for(const id of proteinSettingIds)if(saved[id]!==undefined)$('#'+id).value=saved[id]}catch{}

function setStatus(text,mode=''){els.status.className=`status-line ${mode}`;els.status.lastElementChild.textContent=text}
function normalizeText(value){return String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('_',' ').replace(/\s+/g,' ').trim()}
function gramsFor(label,food=null){if(food?.portionG)return food.portionG;const key=normalizeText(label);const mapped=FOOD101[key];const mappedFood=mapped&&FOOD_DATA.find(item=>item.id===mapped[0]);if(mappedFood?.portionG)return mappedFood.portionG;const sizes=[['soup',330],['ramen',450],['pho',450],['pizza',120],['salad',250],['steak',170],['rice',158],['pasta',140],['hamburger',220],['cake',100],['ice cream',100],['sushi',200],['tacos',150]];return sizes.find(([name])=>key.includes(name))?.[1]||230}
function mapCandidate(label){const raw=String(label||'').replace(/^a photo of\s+/i,'');const low=normalizeText(raw);const entry=FOOD101[low];if(entry){return {id:entry[0],name:entry[1],raw,food:FOOD_DATA.find(f=>f.id===entry[0])||null}}const food=FOOD_DATA.find(f=>f.visualLabel&&normalizeText(f.visualLabel)===low)||FOOD_DATA.find(f=>f.aliases.some(a=>normalizeText(a)===low));return {id:food?.id||null,name:food?.name||raw.replace(/\b\w/g,c=>c.toUpperCase()),raw,food:food||null}}
async function loadClassifier(){if(classifier)return classifier;setStatus('Preparando el modelo de alimentos… La primera descarga puede tardar.','loading');if(!pipeline){const runtime=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.7.2');pipeline=runtime.pipeline;env=runtime.env;env.allowLocalModels=false}classifier=await pipeline('image-classification','onnx-community/swin-finetuned-food101-ONNX',{dtype:'q4'});return classifier}
async function loadBroadClassifier(){if(broadClassifier)return broadClassifier;if(!pipeline){const runtime=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.7.2');pipeline=runtime.pipeline;env=runtime.env;env.allowLocalModels=false}broadClassifier=await pipeline('zero-shot-image-classification','Xenova/clip-vit-base-patch32',{dtype:'q4f16'});return broadClassifier}
async function classifyFood101(){const model=await loadClassifier();const result=await model(els.photoPreview,{top_k:5});candidates=result.map(r=>({...mapCandidate(r.label),score:r.score,source:'food101'}));selectedFood=null;mealFoods=[];renderSuggestions();renderQuickFoods();renderFoodItems();updateNutrition()}
async function runFood101Recognition(){if(!previewUrl)return;els.broad.disabled=true;const originalText=els.broad.textContent;els.broad.textContent='Cargando Food-101…';setStatus('Cargando la alternativa ligera para esta foto…','loading');try{await classifyFood101();setStatus('Food-101 propone nombres de platillos dentro de sus 101 categorías. Confirma el que coincida; tampoco mide la porción.')}catch(err){console.error(err);setStatus(`No se pudo cargar Food-101 (${String(err?.message||err).replace(/\s+/g,' ').slice(0,90)}). Puedes buscar el alimento manualmente.`,'error')}finally{els.broad.disabled=false;els.broad.textContent=originalText}}
async function runBroadRecognition(){if(!previewUrl||!els.broad)return;els.broad.disabled=true;els.broad.textContent='Cargando reconocimiento amplio…';setStatus('Preparando CLIP. La primera vez descarga el modelo (~126 MB); el análisis de la foto se hace en este iPhone.','loading');try{const model=await loadBroadClassifier();const options=new Map();for(const food of FOOD_DATA){const label=food.visualLabel||food.aliases.find(alias=>/[a-z]/i.test(alias))||food.name;const key=normalizeText(label);if(!options.has(key)||food.visualLabel)options.set(key,label)}const prompts=[...options.values()].map(label=>`a photo of ${label}`);const result=await model(els.photoPreview,prompts,{top_k:5});candidates=result.map(item=>({...mapCandidate(item.label),score:item.score,source:'clip'}));selectedFood=null;mealFoods=[];renderSuggestions();renderQuickFoods();renderFoodItems();updateNutrition();setStatus('CLIP ordena opciones por similitud y analiza la foto en este dispositivo. Confirma el platillo, porque la similitud no verifica ingredientes ni cantidades.')}catch(err){console.error(err);try{await classifyFood101();setStatus(`CLIP no pudo cargarse (${String(err?.message||err).replace(/\s+/g,' ').slice(0,75)}). Mostré opciones de Food-101; puedes buscar el ingrediente manualmente.`,'error')}catch(fallbackErr){console.error(fallbackErr);candidates=[];selectedFood=null;mealFoods=[];renderSuggestions();renderQuickFoods();renderFoodItems();updateNutrition();setStatus('No se pudieron cargar los modelos. Puedes buscar el alimento manualmente cuando haya conexión.','error')}}finally{els.broad.disabled=false;els.broad.textContent='Probar alternativa ligera · Food-101'}}function renderSuggestions(){els.suggestions.replaceChildren();candidates.forEach((c,i)=>{const b=document.createElement('button');b.className='suggestion'+(selectedFood?.raw===c.raw?' selected':'');b.innerHTML=`${escapeHtml(c.name)} <small>Opción ${i+1}</small>`;b.addEventListener('click',()=>chooseCandidate(i));els.suggestions.append(b)})}
function makeItem(food,grams,unit,amount,gramsPerUnit){const resolvedUnit=unit??food.portionUnit??'g';const resolvedGramsPerUnit=gramsPerUnit??(resolvedUnit==='g'?1:(food.portionGrams||1));const resolvedAmount=amount??(resolvedUnit==='g'?grams:grams/resolvedGramsPerUnit);return {...food,grams,unit:resolvedUnit,amount:resolvedAmount,gramsPerUnit:resolvedGramsPerUnit}}
function tacoConfig(type){return {pastor:{name:'Tacos al pastor',meat:'pastor_meat',perTaco:30,extras:[['pico',10],['pineapple',5],['salsa',4]]},arrachera:{name:'Tacos de arrachera',meat:'arrachera',perTaco:35,extras:[['pico',10],['salsa',4]]},pollo:{name:'Tacos de pollo',meat:'pollo',perTaco:35,extras:[['pico',10],['salsa',4]]},carnitas:{name:'Tacos de carnitas',meat:'carnitas_meat',perTaco:35,extras:[['pico',10],['salsa',4]]}}[type]}
function tacoExamples(key){try{return allMeals.filter(m=>m.recipeType===key&&m.foods?.length&&Number(m.servingCount)>0).slice(-12)}catch{return []}}
function median(values){const sorted=values.filter(Number.isFinite).sort((a,b)=>a-b);if(!sorted.length)return 0;const mid=Math.floor(sorted.length/2);return sorted.length%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2}
function learnTacoItems(key,base,count){const examples=tacoExamples(key);if(!examples.length)return {items:base,examples:0};const rows=examples.map(meal=>{const servings=Math.max(1,Number(meal.servingCount)||1);return new Map(meal.foods.map(saved=>[saved.id,{grams:(Number(saved.grams)||0)/servings,amount:(Number(saved.amount)||0)/servings,unit:saved.unit||'g'}]))});const ids=[...new Set(rows.flatMap(row=>[...row.keys()]))];const minPresence=Math.floor(examples.length/2)+1;const learned=[];for(const id of ids){const values=rows.map(row=>row.get(id)||{grams:0,amount:0,unit:'g'});const present=values.filter((_,i)=>rows[i].has(id));if(present.length<minPresence)continue;const food=FOOD_DATA.find(f=>f.id===id);if(!food)continue;const gramsPerTaco=median(values.map(value=>value.grams));const quantityPerTaco=median(values.map(value=>value.amount));const unit=present.at(-1)?.unit||'g';const gramsPerUnit=unit==='g'?1:(quantityPerTaco?gramsPerTaco/quantityPerTaco:1);learned.push({...makeItem(food,gramsPerTaco*count,unit,quantityPerTaco*count,gramsPerUnit),scaleWithServings:true})}return {items:learned.length?learned:base,examples:examples.length}}
function learnDishItems(key,base){const wanted=normalizeText(key);const examples=allMeals.filter(meal=>normalizeText(meal.dishClass)===wanted&&meal.foods?.length).slice(-8);if(examples.length<2)return {items:base,examples:0};const rows=examples.map(meal=>new Map(meal.foods.map(saved=>[saved.id,{grams:Number(saved.grams)||0,amount:Number(saved.amount)||0,unit:saved.unit||'g'}])));const ids=[...new Set(rows.flatMap(row=>[...row.keys()]))];const minPresence=Math.floor(examples.length/2)+1;const learned=[];for(const id of ids){const values=rows.map(row=>row.get(id)||{grams:0,amount:0,unit:'g'});const present=values.filter((_,i)=>rows[i].has(id));if(present.length<minPresence)continue;const food=FOOD_DATA.find(item=>item.id===id);if(!food)continue;const grams=median(values.map(value=>value.grams));const amount=median(values.map(value=>value.amount));const unit=present.at(-1)?.unit||'g';learned.push(makeItem(food,grams,unit,amount,unit==='g'?1:(amount?grams/amount:1)))}return {items:learned.length?learned:base,examples:learned.length?examples.length:0}}
function loadTacoTemplate(type='pastor',count=4){const find=id=>FOOD_DATA.find(f=>f.id===id);const config=tacoConfig(type);recipeType=`tacos_${type}`;servingCount=count;els.servings.value=count;els.recipeControls.hidden=false;els.recipeControls.querySelector('label').textContent=`Cantidad de tacos · ${config.name}`;const base=[makeItem(find('tortilla'),count*25,'piezas',count,25),makeItem(find(config.meat),count*config.perTaco,'g',count*config.perTaco,1),...config.extras.map(([id,perTaco])=>makeItem(find(id),count*perTaco,'g',count*perTaco,1))].map(x=>({...x,scaleWithServings:true}));const learned=learnTacoItems(recipeType,base,count);mealFoods=learned.items;selectedFood={id:recipeType,name:config.name,raw:config.name,food:null};renderFoodItems();updateNutrition();setStatus(learned.examples?`Plantilla de ${config.name} ajustada con ${learned.examples} comida(s) guardada(s). Revisa cada componente y cantidad.`:`Plantilla inicial de ${config.name}. Guarda correcciones con pesos reales para personalizar futuras porciones.`)}
function renderQuickFoods(){els.quickFoods.replaceChildren();const addButton=(label,action)=>{const b=document.createElement('button');b.className='quick-food';b.textContent=label;b.onclick=action;els.quickFoods.append(b)};[['Tacos al pastor','pastor'],['Tacos de arrachera','arrachera'],['Tacos de pollo','pollo'],['Tacos de carnitas','carnitas']].forEach(([label,type])=>addButton(label,()=>loadTacoTemplate(type)));['arrachera','pollo','carne','tortilla','salsa','frijoles','huevo','egg_white','arroz','pasta','salmon'].forEach(id=>{const food=FOOD_DATA.find(f=>f.id===id);addButton(food.name,()=>{const amount=gramsFor(food.name.toLowerCase(),food);recipeType='';els.recipeControls.hidden=true;mealFoods=[makeItem(food,amount)];selectedFood={id:food.id,name:food.name,raw:food.name,food};renderFoodItems();updateNutrition();setStatus(`Elegiste ${food.name}. Cambia la unidad o ajusta sus gramos; en huevo puedes registrar huevos o claras.`)})})}
function chooseCandidate(i){const c=candidates[i];selectedFood=c;renderSuggestions();if(!c.food||c.id==='tacos'){mealFoods=[];recipeType='';els.recipeControls.hidden=true;renderFoodItems();updateNutrition();setStatus(c.id==='tacos'?'La foto sugiere tacos, pero no identifica el relleno. Elige una plantilla o añade cada ingrediente por separado.':`El modelo sugiere “${c.name}”, pero no tengo una equivalencia nutricional fiable. Elige el alimento correcto abajo.`,'error');return}recipeType='';els.recipeControls.hidden=true;const amount=gramsFor(c.raw.toLowerCase(),c.food);const learned=learnDishItems(c.raw,[makeItem(c.food,amount)]);mealFoods=learned.items;renderFoodItems();updateNutrition();setStatus(learned.examples?`Usé el desglose mediano de ${learned.examples} comidas tuyas etiquetadas como “${c.name}”. Revísalo y corrige lo que cambie.`:`Seleccionaste ${c.name}. Elige también el método de cocción si afecta el alimento y ajusta la porción.`)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function renderFoodItems(){els.foodItems.replaceChildren();mealFoods.forEach((food,i)=>{const row=document.createElement('div');row.className='food-row';const name=document.createElement('span');name.className='food-name';name.textContent=food.name;const controls=document.createElement('div');controls.className='food-controls';const weight=document.createElement('input');weight.className='food-amount';weight.type='number';weight.min='0';weight.step='1';weight.value=Number(food.grams.toFixed(1));weight.setAttribute('aria-label',`Gramos de ${food.name}`);weight.inputMode='decimal';const g=document.createElement('span');g.className='food-unit';g.textContent='g';if(food.unit==='g'){weight.oninput=()=>{food.grams=Math.max(0,Number(weight.value)||0);food.amount=food.grams;updateNutrition()};controls.append(weight,g)}else{const qty=document.createElement('input');qty.className='food-quantity';qty.type='number';qty.min='0';qty.step='1';qty.value=Number(food.amount.toFixed(1));qty.setAttribute('aria-label',`Cantidad de ${food.name}`);qty.inputMode='decimal';const unit=document.createElement('span');unit.className='food-unit';unit.textContent=food.unit;const eq=document.createElement('span');eq.className='food-equals';eq.textContent='≈';qty.oninput=()=>{food.amount=Math.max(0,Number(qty.value)||0);food.grams=food.amount*food.gramsPerUnit;weight.value=Number(food.grams.toFixed(1));updateNutrition()};weight.oninput=()=>{food.grams=Math.max(0,Number(weight.value)||0);food.amount=food.grams/food.gramsPerUnit;qty.value=Number(food.amount.toFixed(1));updateNutrition()};controls.append(qty,unit,eq,weight,g)}const remove=document.createElement('button');remove.className='food-remove';remove.textContent='×';remove.setAttribute('aria-label',`Quitar ${food.name}`);remove.onclick=()=>{mealFoods.splice(i,1);renderFoodItems();updateNutrition()};row.append(name,controls,remove);els.foodItems.append(row)})}
function updateNutrition(){const total=mealFoods.reduce((sum,f)=>{const q=(Number(f.grams)||0)/100;return {kcal:sum.kcal+f.kcal*q,p:sum.p+f.p*q,c:sum.c+f.c*q,f:sum.f+f.f*q}},{kcal:0,p:0,c:0,f:0});els.cal.textContent=Math.round(total.kcal);els.protein.textContent=`${total.p.toFixed(1)} g`;els.carbs.textContent=`${total.c.toFixed(1)} g`;els.fat.textContent=`${total.f.toFixed(1)} g`;$('#saveMeal').disabled=!mealFoods.length}
function displayName(food){return food.name}
function logProteinShake(){const scoops=Math.max(0,Number($('#proteinScoops').value)||0);if(!scoops)return;const perScoop={p:Math.max(0,Number($('#proteinPerScoop').value)||0),c:Math.max(0,Number($('#proteinCarbsPerScoop').value)||0),f:Math.max(0,Number($('#proteinFatPerScoop').value)||0)};const kcalField=$('#proteinKcalPerScoop').value.trim();const kcalPerScoop=kcalField===''?perScoop.p*4+perScoop.c*4+perScoop.f*9:Math.max(0,Number(kcalField)||0);const total={p:scoops*perScoop.p,kcal:scoops*kcalPerScoop,c:scoops*perScoop.c,f:scoops*perScoop.f};meals.push({day:todayKey,foods:[{id:'protein_powder',name:'Shake de proteína',grams:total.p,amount:scoops,unit:'scoop'}],grams:total.p,kcal:Math.round(total.kcal),p:+total.p.toFixed(1),c:+total.c.toFixed(1),f:+total.f.toFixed(1),scoops,proteinGrams:+total.p.toFixed(1),proteinShake:true,time:new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}),photo:'',recipeType:'',dishClass:''});persist();const feedback=$('#proteinLogFeedback');feedback.textContent=`Añadido: ${scoops} ${scoops===1?'scoop':'scoops'} · ${total.p.toFixed(1)} g de proteína.`;feedback.hidden=false}
function searchFoods(query){return FOOD_DATA.map(food=>{const name=normalizeText(food.name);const aliases=food.aliases.map(normalizeText);let rank=99;if(name===query)rank=0;else if(aliases.includes(query))rank=food.visualLabel?1:2;else if(name.startsWith(query))rank=3;else if(aliases.some(alias=>alias.startsWith(query)))rank=4;else if(name.includes(query)||aliases.some(alias=>alias.includes(query)))rank=5;return {food,rank}}).filter(result=>result.rank<99).sort((a,b)=>a.rank-b.rank||Number(Boolean(b.food.visualLabel))-Number(Boolean(a.food.visualLabel))).slice(0,7).map(result=>result.food)}
async function thumbnail(file){return new Promise(resolve=>{const image=new Image();image.onload=()=>{const scale=Math.min(1,320/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.58))};image.onerror=()=>resolve('');image.src=previewUrl})}
async function analyze(file){if(!file)return;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);els.photoPreview.src=previewUrl;activePhoto=await thumbnail(file);els.photoPreview.hidden=false;els.photoDrop.classList.add('has-photo');els.results.hidden=false;els.broad.hidden=false;els.broad.disabled=true;recipeType='';els.recipeControls.hidden=true;selectedFood=null;mealFoods=[];renderSuggestions();renderFoodItems();updateNutrition();renderQuickFoods();setStatus('Analizando la foto con el reconocedor amplio en este dispositivo…','loading');await runBroadRecognition()}function renderHistory(){els.history.replaceChildren();if(!meals.length){const p=document.createElement('div');p.className='history-empty';p.textContent='Tus comidas que guardes aparecerán aquí.';els.history.append(p)}else meals.slice().reverse().forEach((meal,index)=>{const item=document.createElement('div');item.className='history-item';const thumb=document.createElement('div');thumb.className='history-thumb';if(meal.photo){const img=document.createElement('img');img.src=meal.photo;img.alt='';thumb.append(img)}else thumb.textContent='✳';const info=document.createElement('div');info.className='history-info';const names=meal.foods.map(x=>x.name).join(' + ');const detail=meal.proteinShake?`${meal.scoops} ${meal.scoops===1?'scoop':'scoops'} · ${meal.proteinGrams} g proteína · ${meal.time}`:`${meal.grams} g · ${meal.time}`;info.innerHTML=`<strong>${escapeHtml(names)}</strong><span>${detail}</span>`;const kcal=document.createElement('span');kcal.className='history-kcal';kcal.textContent=`${meal.kcal} kcal`;const remove=document.createElement('button');remove.className='remove-meal';remove.setAttribute('aria-label','Quitar comida');remove.textContent='×';remove.onclick=()=>{meals.splice(meals.length-1-index,1);persist()};item.append(thumb,info,kcal,remove);els.history.append(item)});const total=meals.reduce((a,m)=>({k:a.k+m.kcal,p:a.p+m.p,c:a.c+m.c,f:a.f+m.f}),{k:0,p:0,c:0,f:0});$('#dailyCalories').textContent=Math.round(total.k);$('#dailyProtein').textContent=`${total.p.toFixed(1)} g`;$('#dailyCarbs').textContent=`${total.c.toFixed(1)} g`;$('#dailyFat').textContent=`${total.f.toFixed(1)} g`;$('#mealCount').textContent=`${meals.length} ${meals.length===1?'comida':'comidas'}`}
function persist(){allMeals=[...allMeals.filter(m=>m.day!==todayKey),...meals];localStorage.setItem('comida-clara-meals',JSON.stringify(allMeals));renderHistory()}
els.photoInput.addEventListener('change',e=>analyze(e.target.files?.[0]));
els.broad.addEventListener('click',runFood101Recognition);
els.servings.addEventListener('input',()=>{if(!recipeType.startsWith('tacos_'))return;const next=Math.max(1,Math.min(20,Number(els.servings.value)||1));const factor=next/servingCount;mealFoods.filter(f=>f.scaleWithServings).forEach(f=>{f.grams*=factor;f.amount*=factor});servingCount=next;renderFoodItems();updateNutrition()});
els.search.addEventListener('input',()=>{const q=normalizeText(els.search.value);els.searchResults.replaceChildren();if(!q){els.searchResults.hidden=true;return}const matches=searchFoods(q);matches.forEach(food=>{const b=document.createElement('button');b.className='search-result';b.innerHTML=`<span>${escapeHtml(food.name)}</span><small>${food.kcal} kcal / 100 g · P ${food.p} · C ${food.c} · G ${food.f}</small>`;b.onclick=()=>{const templates={tacos_pastor:'pastor',tacos_carnitas:'carnitas',tacos_pollo:'pollo'};if(templates[food.id]){loadTacoTemplate(templates[food.id]);els.search.value='';els.searchResults.hidden=true;return}if(food.id==='tacos'){mealFoods=[];recipeType='';els.recipeControls.hidden=true;renderFoodItems();updateNutrition();setStatus('Elige el tipo de taco arriba para desglosar relleno e ingredientes.');els.search.value='';els.searchResults.hidden=true;return}if(!mealFoods.some(x=>x.id===food.id))mealFoods.push(makeItem(food,food.portionG||100));renderFoodItems();updateNutrition();els.search.value='';els.searchResults.hidden=true};els.searchResults.append(b)});els.searchResults.hidden=!matches.length});document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))els.searchResults.hidden=true});
$('#logProtein').addEventListener('click',logProteinShake);$('#saveMeal').addEventListener('click',()=>{if(!mealFoods.length)return;const sum=mealFoods.reduce((a,f)=>{const q=(Number(f.grams)||0)/100;return {k:a.k+f.kcal*q,p:a.p+f.p*q,c:a.c+f.c*q,f:a.f+f.f*q,grams:a.grams+(Number(f.grams)||0)}},{k:0,p:0,c:0,f:0,grams:0});meals.push({day:todayKey,foods:mealFoods.map(x=>({id:x.id,name:x.name,grams:x.grams,amount:x.amount,unit:x.unit})),grams:sum.grams,kcal:Math.round(sum.k),p:+sum.p.toFixed(1),c:+sum.c.toFixed(1),f:+sum.f.toFixed(1),time:new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}),photo:activePhoto,recipeType,dishClass:recipeType||selectedFood?.raw||'',servingCount});persist();resetForm()});
function resetForm(){els.photoInput.value='';els.photoPreview.hidden=true;els.photoDrop.classList.remove('has-photo');els.results.hidden=true;els.broad.hidden=true;activePhoto='';if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl='';candidates=[];mealFoods=[];selectedFood=null;recipeType='';els.recipeControls.hidden=true;setStatus('El análisis visual se carga al elegir una foto.');els.search.value='';els.quickFoods.replaceChildren()}
$('#cancelMeal').addEventListener('click',resetForm);$('#clearDay').addEventListener('click',()=>{if(meals.length&&confirm('¿Borrar las comidas registradas hoy?')){meals=[];persist()}});$('#exportExamples').addEventListener('click',()=>{const records=JSON.parse(localStorage.getItem('comida-clara-meals')||'[]');if(!records.length){alert('Aún no hay comidas guardadas para exportar.');return}const data={format:'comida-clara-training-examples-v1',notice:'Fotos y etiquetas corregidas por el usuario; esta exportación no significa que el modelo se haya reentrenado.',examples:records.map(({day,time,foods,recipeType,dishClass,servingCount,photo})=>({day,time,dish:recipeType||foods.map(f=>f.name).join(' + '),dishClass,servingCount,ingredients:foods.map(f=>({name:f.name,quantity:f.amount,unit:f.unit,grams:f.grams})),photo}))};const blob=new Blob([JSON.stringify(data)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='comida-clara-ejemplos-etiquetados.json';link.click();URL.revokeObjectURL(url)});$('#todayDate').textContent=new Intl.DateTimeFormat('es-MX',{weekday:'short',day:'numeric',month:'short'}).format(new Date());
const dialog=$('#aboutDialog');$('#aboutButton').onclick=()=>dialog.showModal();$('#closeDialog').onclick=()=>dialog.close();$('#closeDialogAction').onclick=()=>dialog.close();
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installButton').hidden=false});$('#installButton').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installButton').hidden=true}else alert('En Safari, toca Compartir y luego “Agregar a pantalla de inicio”.')};
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
for(const id of proteinSettingIds)$('#'+id).addEventListener('change',()=>{const saved=Object.fromEntries(proteinSettingIds.map(key=>[key,$('#'+key).value]));try{localStorage.setItem('comida-clara-protein-settings',JSON.stringify(saved))}catch{}});
renderHistory();
